"""RESUMED INDEPENDENT DELTA REVIEW 06 probes: invocation-scoped availability (reference only)."""
import ast
import copy
import hashlib
import json
import sys
import types
from pathlib import Path
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

S = Path(__file__).resolve().parent / 'subject'
M = {f['path']: f['sha256'] for f in json.loads((S.parent / 'manifest.json').read_bytes())['files']}


def verified(rel):
    data = (S / rel).read_bytes()
    assert hashlib.sha256(data).hexdigest() == M[rel], rel
    return data


for p in json.loads(verified('input-pins.json'))['inputs']:
    b = (S / p['path']).read_bytes()
    assert len(b) == p['bytes'] and hashlib.sha256(b).hexdigest() == p['sha256'], p['path']
ref = types.ModuleType('ref'); exec(compile(verified('inputs/canonical.py'), 'canonical.py', 'exec'), ref.__dict__)
docs = {}
for path in sorted((S / 'inputs/schemas').glob('*.json')):
    d = ref.parse(verified(str(path.relative_to(S)))); docs[d['$id']] = d
V6 = ref.parse(verified('command-envelope.v6.schema.json')); docs[V6['$id']] = V6
REG = Registry().with_resources((k, Resource(contents={a: v for a, v in d.items() if a != '$schema'}, specification=DRAFT202012)) for k, d in docs.items())
INV_ID, ENV_ID = 'urn:opensip:product-v1:workflows:evaluator3:invocation:3', V6['$id']
join = types.ModuleType('join'); exec(compile(verified('ledger_join.py'), 'ledger_join.py', 'exec'), join.__dict__)
inventory = json.loads(verified('inputs/inventory5.json'))
fx = json.loads(verified('inputs/report-fixtures04.json'))

# native owner projector: my own extraction of exactly the two functions and the remedy table
ntree = ast.parse(verified('inputs/native_evidence_model.v2.py'))
nodes = [n for n in ntree.body if (isinstance(n, ast.FunctionDef) and n.name in ('release_absence_notices', 'invocation_availability'))
         or (isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'PUBLIC_ROUTE_REMEDIES' for t in n.targets))]
assert len(nodes) == 3
native = {}; exec(compile(ast.Module(body=nodes, type_ignores=[]), 'native_evidence_model.v2.py#extract', 'exec'), native)
PROJECT = native['invocation_availability']

# workflow owner model with the selected successor (my own extraction)
succ = json.loads(verified('model-successor.json'))
wtext = verified('inputs/workflows_model.v1.py').decode().replace(succ['before'], succ['after'])
WANT = {'Refusal', 'terminate', 'analysis_termination', 'comparison_termination', 'exit_code', 'validate_dag', 'raw_sha', 'synthetic_execution_id', '_exec_id', 'run_invocation'}
wn = []
for n in ast.parse(wtext).body:
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name in WANT:
        wn.append(n)
    elif isinstance(n, ast.Assign):
        names = {x.id for x in n.targets if isinstance(x, ast.Name)}
        if names & WANT or (names and all(x.isupper() for x in names) and not any(isinstance(c, ast.Call) for c in ast.walk(n.value))):
            wn.append(n)
MODEL = types.ModuleType('owner'); MODEL.__dict__.update(hashlib=hashlib, json=json, canonical=ref)
exec(compile(ast.Module(body=wn, type_ignores=[]), 'workflows_model.v1.py#extract', 'exec'), MODEL.__dict__)

gold = fx['deliveryGoldens'][24]['envelope']
ANALYSIS, RID, PID = gold['run'], gold['requestId'], gold['projectId']
RP = fx['bases']['repair-preview']['envelope']['queryRecord']
SNAP = 'snapshot2:' + 'a' * 64
rows, fails = [], []


def shape(v, sid):
    try:
        ref.validate({'$ref': sid}, v, REG); return True
    except Exception as e:
        if type(e).__name__ not in ('ValidationError', 'AdmissionError'): raise
        return False


def row(name, got, want=None, **kw):
    r = {'case': name, 'got': got, **kw}
    if want is not None:
        r['want'] = want; r['ok'] = got == want
        if got != want: fails.append(name)
    else:
        r['observation'] = True
    rows.append(r)


def D(rec, env, ctx):
    try:
        join.validate_interruption_delivery(rec, env, ctx, inventory, PROJECT); return 'accepted'
    except join.JoinRefusal as e:
        return str(e)
    except Exception as e:
        return 'UNTYPED:' + type(e).__name__


def P(ctx, env, name):
    try:
        join.validate_preplanning_delivery(ctx, env, name, inventory, PROJECT); return 'accepted'
    except join.JoinRefusal as e:
        return str(e)
    except Exception as e:
        return 'UNTYPED:' + type(e).__name__


def params(i, kind, reqs, kinds):
    if kind == 'analysis':
        return {'kind': kind, 'profile': 'default', 'role': 'primary', 'durability': 'authoritative', 'snapshotSource': 'live-worktree'}
    if kind == 'render':
        return {'kind': kind, 'format': 'json', 'destination': 'stdout', 'sourceSteps': [j for j in range(i) if reqs[j] == 'required'], 'required': True}
    if kind == 'query':
        rq = copy.deepcopy(gold['advisoryReport']['request'])
        return {'kind': kind, 'operation': rq['operation'], 'completeness': rq['completeness'], 'page': rq['page'], 'request': rq}
    if kind == 'repair-preview':
        d = RP['plan']['descriptor']
        return {'kind': kind, 'evidenceSource': {'runId': d['evidenceRunId']}, 'recipe': copy.deepcopy(d['recipe']), 'targets': copy.deepcopy(d['targets'])}
    if kind == 'repair-apply':
        return {'kind': kind, 'planStep': kinds.index('repair-preview'), 'repairPlanId': RP['plan']['repairPlanId'], 'consentSource': 'policy',
                'authorizationRef': 'security.repair-apply-authorization.v1:' + 'b' * 64}
    if kind == 'verify':
        return {'kind': kind, 'afterStep': kinds.index('repair-apply') if 'repair-apply' in kinds else 0, 'profile': 'default'}


def result_for(i, kind):
    if kind == 'analysis':
        r = copy.deepcopy(ANALYSIS); r['runId'] = 'run3:' + format(i + 1, 'x') * 64; return r
    if kind == 'render':
        return {'kind': 'render', 'format': 'json', 'rendererVersion': 1, 'bytes': 7, 'truncation': False, 'written': True}
    if kind == 'query':
        return {'kind': 'query', 'items': 1, 'truncated': False, 'completenessMet': True, 'advisory': True}
    if kind == 'repair-preview':
        r = copy.deepcopy(RP['preview']); r['applicable'] = True; return r
    if kind == 'repair-apply':
        return {'kind': 'repair-apply', 'receiptId': 'receipt2:' + 'b' * 64, 'effectOutcome': 'COMPLETED', 'journalState': 'COMMITTED', 'rollback': 'not-needed', 'appliedSnapshotId': SNAP}
    if kind == 'verify':
        r = copy.deepcopy(ANALYSIS); r.update(kind='verify', runId='run3:' + 'd' * 64)
        r['verification'] = {'appliedSnapshotId': SNAP, 'verifiedSnapshotId': SNAP, 'snapshotMatched': True, 'targetsRemaining': 0, 'netNewFindings': 0}
        return r


def ledger(kinds, reqs=None, cut=None, sig='SIGINT', over=None, workflow=None):
    reqs = reqs or ['required'] * len(kinds)
    steps = [{'stepId': i, 'kind': k, 'requirement': reqs[i], 'dependsOn': [j for j in range(i) if reqs[j] == 'required' or reqs[i] == 'optional'],
              'dependencyGate': 'terminal' if k == 'render' else 'completed', 'retryPolicy': 'none', 'params': params(i, k, reqs, kinds)} for i, k in enumerate(kinds)]
    wf = workflow or {'kind': 'profile', 'contributionId': 'org.example.workflow', 'activationId': 'review', 'profileVersion': '1.0.0'}
    rec0 = {'schemaFamily': 'opensip.product.invocation', 'schemaMajor': 3, 'requestId': RID, 'projectId': PID, 'workflow': wf,
            'mode': {'interactive': False, 'ci': True, 'ephemeral': False}, 'orderedSteps': steps}
    sc = {str(i): [{'event': 'completed', 'result': result_for(i, k)}] for i, k in enumerate(kinds)}
    sc.update(over or {})
    if cut is not None:
        sc['cancelAt'] = {'stepId': cut, 'signal': sig}
    return MODEL.run_invocation(rec0, sc)[0]


def details(rec):
    return [r['termination']['domainDetail'] for r in rec['stepResults'] if r['outcome'] not in ('cancelled', 'skipped')
            and r['termination']['class'] in ('request-rejected', 'operational-failed') and 'domainDetail' in r['termination']]


def carrier(rec, kind=None, selections=None):
    t = rec['termination']
    kind = kind or ('run' if t.get('runId') else ('failure' if t['class'] == 'interrupted' else 'invocation'))
    e = {'schemaFamily': 'opensip.product.envelope', 'schemaMajor': 6, 'kind': kind, 'requestId': rec['requestId'], 'projectId': rec['projectId'],
         'termination': copy.deepcopy(t), 'exitCode': MODEL.exit_code(t)}
    if kind == 'run':
        e['run'] = copy.deepcopy(next(r['result'] for r in reversed(rec['stepResults']) if r.get('result', {}).get('runId') == t['runId']))
    elif kind == 'invocation':
        e['invocation'] = copy.deepcopy(rec)
    ds = details(rec)
    if t['class'] == 'interrupted' and (ds or kind == 'failure'):
        e['errors'] = copy.deepcopy(ds)
    if selections is not None:
        e['availability'] = PROJECT([(s['stepId'], s['undeclared']) for s in selections])
    return e


def ctx(rec, selections):
    return {'requestId': rec['requestId'], 'workflow': copy.deepcopy(rec['workflow']), 'perStep': copy.deepcopy(selections)}


def notice(root='packages/a', cap='call-graph'):
    return {'capabilityId': cap, 'languageMode': 'typescript', 'workspaceRoot': root}


# ============ S. schema delta
old_not = {x['required'][0] for x in json.loads((S.parent.parent.parent / 'm1-interruption-envelope-subject-05' / 'command-envelope.v6.schema.json').read_bytes())['allOf'][19]['then']['oneOf'][1]['not']['anyOf']}
new_not = {x['required'][0] for x in V6['allOf'][19]['then']['oneOf'][1]['not']['anyOf']}
row('S1-not-list-delta', sorted(old_not - new_not) + sorted(new_not - old_not), ['availability'], note='read-only comparison against frozen subject05 schema bytes')
pre = ledger(['analysis', 'render'], cut=0, workflow={'kind': 'builtin', 'name': 'default'})
e = carrier(pre, selections=[])
row('S2-empty-errors-form-with-empty-account', (e['errors'], shape(e, ENV_ID)), ([], True))
e2 = copy.deepcopy(e); e2['availability'] = {'stepCount': 5, 'totalNoticeCount': 9, 'steps': []}
row('S3-shape-cannot-bind-counts', (shape(e2, ENV_ID), D(pre, e2, ctx(pre, []))), (True, 'J-AVAILABILITY-PROJECTION'), note='counts are only enforced by the composite join')
for f in ('findings', 'advisoryReport'):
    e3 = copy.deepcopy(e); e3[f] = gold[f]
    row('S4-empty-form-still-forbids-' + f, shape(e3, ENV_ID), False)

# ============ A. owner-model ledgers with retained selections across cuts
cases = []
for label, kinds, reqs, wf, sel_steps in [
    ('default', ['analysis', 'render'], None, {'kind': 'builtin', 'name': 'default'}, [0]),
    ('fit', ['analysis', 'query', 'render'], None, {'kind': 'builtin', 'name': 'fit'}, [0]),
    ('repair-apply', ['repair-preview', 'repair-apply', 'verify', 'render'], None, {'kind': 'builtin', 'name': 'repair-apply'}, [2]),
    ('profile-opt-analysis-verifyless', ['analysis', 'analysis', 'render'], ['optional', 'required', 'required'], None, [0, 1]),
]:
    for cut in [None] + list(range(len(kinds) + 1)):
        rec = ledger(kinds, reqs, cut, workflow=wf)
        started = [s for s in sel_steps if rec['stepResults'][s]['outcome'] not in ('cancelled', 'skipped')]
        sels = [{'stepId': s, 'undeclared': [notice('u%d' % s)]} for s in started]
        env = carrier(rec)
        req_parity = wf is None or 'capability-availability' in next(c for c in inventory['commands'] if c['name'] == wf['name'])['parityFields']
        if sels or req_parity:
            env['availability'] = PROJECT([(s['stepId'], s['undeclared']) for s in sels])
        g = (shape(rec, INV_ID), shape(env, ENV_ID), D(rec, env, ctx(rec, sels)))
        cases.append({'wf': label, 'cut': cut, 'term': rec['termination']['class'], 'selected': started, 'result': g})
        if g != (True, True, 'accepted'):
            fails.append('A-%s-%s' % (label, cut))
        # omission of the retained account is refused whenever something was retained or parity requires it
        if 'availability' in env:
            e4 = copy.deepcopy(env); e4.pop('availability')
            if D(rec, e4, ctx(rec, sels)) != 'J-AVAILABILITY-PROJECTION':
                fails.append('A-omission-%s-%s' % (label, cut))
row('A1-owner-ledgers-with-retained-selections', {'count': len(cases), 'allAccepted': all(c['result'] == (True, True, 'accepted') for c in cases)}, {'count': 20, 'allAccepted': True}, detail=cases)
baseline_upgrade_rec = ledger(['analysis', 'render'], cut=1, workflow={'kind': 'builtin', 'name': 'baseline-upgrade'})
row('A2-baseline-upgrade-no-parity', {'shape': shape(baseline_upgrade_rec, INV_ID),
    'noSelectionAbsent': D(baseline_upgrade_rec, carrier(baseline_upgrade_rec), ctx(baseline_upgrade_rec, [])),
    'noSelectionEmptyAccountInvented': D(baseline_upgrade_rec, carrier(baseline_upgrade_rec, selections=[]), ctx(baseline_upgrade_rec, [])),
    'selectionPresent': D(baseline_upgrade_rec, carrier(baseline_upgrade_rec, selections=[{'stepId': 0, 'undeclared': []}]), ctx(baseline_upgrade_rec, [{'stepId': 0, 'undeclared': []}])),
    'selectionOmitted': D(baseline_upgrade_rec, carrier(baseline_upgrade_rec), ctx(baseline_upgrade_rec, [{'stepId': 0, 'undeclared': []}]))},
    {'shape': True, 'noSelectionAbsent': 'accepted', 'noSelectionEmptyAccountInvented': 'J-AVAILABILITY-PROJECTION', 'selectionPresent': 'accepted', 'selectionOmitted': 'J-AVAILABILITY-PROJECTION'},
    note='inventory steps are [analysis, mutation, render]; a two-step ledger is used only to exercise the no-parity branch')

# ============ B. counterexamples to selection binding
nr = ledger(['analysis', 'render'], cut=0, workflow={'kind': 'builtin', 'name': 'default'})   # step 0 cancelled before start
never = [{'stepId': 0, 'undeclared': [notice()]}]
row('B1-selection-on-never-started-cancelled-step', {'attempts': nr['stepResults'][0]['attempts'], 'outcome': nr['stepResults'][0]['outcome'],
    'join': D(nr, carrier(nr, selections=never), ctx(nr, never))},
    {'attempts': [], 'outcome': 'cancelled', 'join': 'accepted'},
    note='owner model: cancelAt means the signal arrived BEFORE step k started (attempts []); no selection can have been made, yet a nonempty account is admitted (finding N1)')
rej = ledger(['analysis', 'analysis', 'render'], ['optional', 'required', 'required'], cut=1,
             over={'0': [{'event': 'rejected', 'errorCode': 'CONFIG.INVALID', 'detail': 'CONFIG.INVALID', 'remedy': 'fix'}]})
row('B2-selection-on-rejected-step-with-attempt', {'attempts': len(rej['stepResults'][0]['attempts']), 'join': D(rej, carrier(rej, selections=never), ctx(rej, never)),
    'errors': carrier(rej)['errors']}, {'attempts': 1, 'join': 'accepted', 'errors': [{'code': 'CONFIG.INVALID', 'remedy': 'fix'}]},
    note='lawful: a rejected attempt may have selected before rejection; error and availability coexist')
rej0 = copy.deepcopy(rej); rej0['stepResults'][0]['attempts'] = []
row('B3-selection-on-rejected-step-without-attempt', (shape(rej0, INV_ID), D(rej0, carrier(rej0, selections=never), ctx(rej0, never))), (True, 'accepted'),
    note='admission-time rejection (attempts []) cannot have selected; still admitted (N1)')
done = ledger(['analysis', 'render'], cut=1, workflow={'kind': 'builtin', 'name': 'default'})   # analysis completed, Run committed
